export const advancedAssets = {
  "charts/kubelab/Chart.yaml": "apiVersion: v2\nname: kubelab-example\nversion: 0.1.0\ntype: application\n",
  "charts/kubelab/values.yaml": "replicaCount: 1\nimage: kubelab:1.0\n",
  "charts/kubelab/templates/deployment.yaml": "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: {{ .Release.Name }}\n  namespace: {{ .Release.Namespace }}\nspec:\n  replicas: {{ .Values.replicaCount }}\n  selector:\n    matchLabels:\n      app: {{ .Release.Name }}\n  template:\n    metadata:\n      labels:\n        app: {{ .Release.Name }}\n    spec:\n      automountServiceAccountToken: false\n      securityContext:\n        runAsNonRoot: true\n        runAsUser: 1000\n        runAsGroup: 1000\n      containers:\n        - name: web\n          image: {{ .Values.image | quote }}\n          imagePullPolicy: Never\n          resources:\n            requests:\n              cpu: 25m\n              memory: 32Mi\n            limits:\n              cpu: 200m\n              memory: 128Mi\n          securityContext:\n            allowPrivilegeEscalation: false\n            readOnlyRootFilesystem: true\n            capabilities:\n              drop: [\"ALL\"]\n",
  "k8s/overlays/dev/kustomization.yaml": "apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\nresources:\n  - ../../lab.yaml\nreplicas:\n  - name: kubelab\n    count: 1\n",
  "lab-operator.mjs": "// Small polling controller for the isolated LabService exercise.\nimport https from 'node:https';\nimport { reconcile } from './lab-operator-model.mjs';\nimport { readFile } from 'node:fs/promises';\nconst credentials = '/var/run/secrets/kubernetes.io/serviceaccount/';\nconst namespace = (await readFile(credentials + 'namespace', 'utf8')).trim();\nif (namespace !== 'kubelab') throw new Error('This learning controller only operates in namespace kubelab.');\nconst ca = await readFile(credentials + 'ca.crt');\nlet stopped = false;\nprocess.on('SIGTERM', () => { stopped = true; });\nasync function request(method, pathname, data) {\n  // Read the projected token for each request so rotation does not require restart.\n  const token = (await readFile(credentials + 'token', 'utf8')).trim();\n  const body = data === undefined ? undefined : JSON.stringify(data);\n  return new Promise((resolve, reject) => {\n    const req = https.request({ hostname: 'kubernetes.default.svc', port: 443, path: pathname, method, ca, timeout: 5000, headers: { Authorization: `Bearer ${token}`, Accept: 'application/json', ...(body ? { 'Content-Type': method === 'PATCH' ? 'application/merge-patch+json' : 'application/json', 'Content-Length': Buffer.byteLength(body) } : {}) } }, res => {\n      let size = 0; const chunks = [];\n      res.on('error', reject);\n      res.on('data', chunk => { size += chunk.length; if (size > 1024 * 1024) res.destroy(new Error('Response exceeds learning limit')); else chunks.push(chunk); });\n      res.on('end', () => { try { const value = JSON.parse(Buffer.concat(chunks).toString('utf8')); resolve({ status: res.statusCode, value }); } catch { reject(new Error('Invalid API response')); } });\n    });\n    req.on('error', reject);\n    req.on('timeout', () => req.destroy(new Error('API timeout')));\n    if (body) req.write(body);\n    req.end();\n  });\n}\nwhile (!stopped) {\n  try {\n    const list = await request('GET', `/apis/training.kubelab.local/v1/namespaces/${namespace}/labservices`);\n    if (list.status !== 200) throw new Error(`List failed: ${list.status}`);\n    for (const resource of list.value.items) { if (stopped) break; await reconcile(resource, { namespace, request, log: line => console.log(line) }); }\n  } catch (error) { console.error(JSON.stringify({ event: 'reconcile-error', reason: error.message })); }\n  if (!stopped) await new Promise(resolve => setTimeout(resolve, 5000));\n}\n",
  "lab-operator-model.mjs": "export function desired(resource, namespace) {\n  const name = `labservice-${resource.metadata.name}`;\n  return { apiVersion: 'apps/v1', kind: 'Deployment', metadata: { name, namespace, ownerReferences: [{ apiVersion: resource.apiVersion, kind: resource.kind, name: resource.metadata.name, uid: resource.metadata.uid, controller: true, blockOwnerDeletion: false }] }, spec: { replicas: resource.spec.replicas ?? 1, selector: { matchLabels: { app: name } }, template: { metadata: { labels: { app: name } }, spec: { automountServiceAccountToken: false, securityContext: { runAsNonRoot: true, runAsUser: 1000, runAsGroup: 1000, seccompProfile: { type: 'RuntimeDefault' } }, containers: [{ name: 'web', image: 'kubelab:1.0', imagePullPolicy: 'Never', env: [{ name: 'LAB_MESSAGE', value: resource.spec.message }], resources: { requests: { cpu: '25m', memory: '32Mi' }, limits: { cpu: '200m', memory: '128Mi' } }, securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: ['ALL'] } } }] } } } };\n}\nexport async function reconcile(resource, { namespace, request, log = () => {} }) {\n  const scope = `/apis/apps/v1/namespaces/${namespace}/deployments`;\n  if (resource.metadata.deletionTimestamp) return;\n  const next = desired(resource, namespace);\n  const route = scope + '/' + encodeURIComponent(next.metadata.name);\n  const current = await request('GET', route);\n  if (current.status === 404) {\n    const result = await request('POST', scope, next);\n    if (result.status !== 201 && result.status !== 409) throw new Error(`Create failed: ${result.status}`);\n    if (result.status === 201) log(JSON.stringify({ event: 'created', resource: resource.metadata.name })); return;\n  }\n  if (current.status !== 200) throw new Error(`Read failed: ${current.status}`);\n  if (!current.value.metadata.ownerReferences?.some(owner => owner.uid === resource.metadata.uid && owner.controller)) throw new Error('Refusing to adopt an unrelated Deployment');\n  const oldContainer = current.value.spec.template.spec.containers.find(x => x.name === 'web');\n  const message = oldContainer?.env?.find(x => x.name === 'LAB_MESSAGE')?.value;\n  // Avoid an update on every polling pass. Only our two teaching fields are managed.\n  if (current.value.spec.replicas === next.spec.replicas && message === resource.spec.message) return;\n  const patch = { metadata: { resourceVersion: current.value.metadata.resourceVersion }, spec: { replicas: next.spec.replicas, template: next.spec.template } };\n  const result = await request('PATCH', route, patch);\n  if (![200, 409].includes(result.status)) throw new Error(`Update failed: ${result.status}`);\n  if (result.status === 200) log(JSON.stringify({ event: 'updated', resource: resource.metadata.name }));\n}\n"
};
